        private static void ImportFullCatalog0850()
        {
            FullContentCatalog0850.EnsureLoaded();
            foreach(var d in FullContentCatalog0850.Root.loot)
            {
                if(d==null||string.IsNullOrWhiteSpace(d.id))continue;
                Loot[d.id]=new LootRuntimeDefinition{Id=d.id,Name=d.name,Category=d.category,Rarity=d.rarity,Value=d.value,StackLimit=d.stackLimit,DropTags=d.dropTags,UsedBy=d.usedBy,Consumable=d.consumable,CraftingMaterial=d.craftingMaterial,QuestItem=d.questItem,Effect=d.effect,Copies=Math.Max(1,d.copies),Status=d.status};
            }
            foreach(var d in FullContentCatalog0850.Root.equipment)
            {
                if(d==null||string.IsNullOrWhiteSpace(d.id))continue;
                Equipment[d.id]=new EquipmentCatalogDefinition{Id=d.id,Name=d.name,Type=d.type,Family=d.family,Rarity=d.rarity,Slot=d.slot,Hands=d.hands,Value=d.value,Attack=d.attack,Armor=d.armor,Range=d.range,DamageType=d.damageType,Ability1=d.ability1,Ability2=d.ability2,Status=d.status};
            }
        }

        private static void AddLoot(string id,string name,string category,string rarity,int value,int stack,string drop,string used,bool consumable,bool material,bool quest,string effect,int copies,string status)
            => Loot[id]=new LootRuntimeDefinition{Id=id,Name=name,Category=category,Rarity=rarity,Value=value,StackLimit=stack,DropTags=drop,UsedBy=used,Consumable=consumable,CraftingMaterial=material,QuestItem=quest,Effect=effect,Copies=Math.Max(1,copies),Status=status};
        private static void AddEquipment(string id,string name,string type,string family,string rarity,string slot,string hands,int value,int attack,int armor,int range,string damage,string ability1,string ability2,string status)
            => Equipment[id]=new EquipmentCatalogDefinition{Id=id,Name=name,Type=type,Family=family,Rarity=rarity,Slot=slot,Hands=hands,Value=value,Attack=attack,Armor=armor,Range=range,DamageType=damage,Ability1=ability1,Ability2=ability2,Status=status};

        public static List<string> BuildLootDeck()
        {
            var deck=new List<string>(); foreach(var def in Loot.Values) for(int i=0;i<def.Copies;i++) deck.Add(def.Id); return deck;
        }
        public static List<string> BuildEquipmentDeck()=>new List<string>(Equipment.Keys);
        public static string LootLabel(string id)=>Loot.TryGetValue(id??string.Empty,out var d)?$"{d.Id} {d.Name} [{d.Rarity}]":id??"?";
        public static bool EquipmentHasAbility(string id)=>Equipment.TryGetValue(id??string.Empty,out var d)&&(!string.IsNullOrWhiteSpace(d.Ability1)||!string.IsNullOrWhiteSpace(d.Ability2));
        public static string EquipmentAbilityText(string id)
        {
            if(!Equipment.TryGetValue(id??string.Empty,out var d))return string.Empty;
            return string.Join(" | ",new[]{d.Ability1,d.Ability2}.Where(x=>!string.IsNullOrWhiteSpace(x)));
        }
        public static string EquipmentLabel(string id)=>Equipment.TryGetValue(id??string.Empty,out var d)?$"{d.Id} {d.Name} [{d.Rarity}]{(EquipmentHasAbility(id)?" [ABILITY]":string.Empty)}":id??"?";
        public static bool IsConsumable(string id)=>Loot.TryGetValue(id??string.Empty,out var d)&&d.Consumable;
    }
